// Fields you want to show (order matters)
const cols = [
  'CoreID',
  'FirstName',
  'LastName',
  'EmailAddress',
  'DistrictName',
  'DataMate_Role',
  'StaffTrac_Role',
];

// Gather data
const rows = $items().map(item => item.json);

// Compute column widths
const colWidths = cols.map(col =>
  Math.max(
    col.length,
    ...rows.map(r => (r[col] == null ? '' : String(r[col]))?.length ?? 0),
  ),
);

// Helper pad
function pad(str, len) {
  str = str == null ? '' : String(str);
  if (str.length < len) return str + ' '.repeat(len - str.length);
  return str;
}

// Build horizontal rule
const rule = '+' + colWidths.map(w => '-'.repeat(w + 2)).join('+') + '+';

// Header row
let text = rule + '\n| ' + cols.map((c, i) => pad(c, colWidths[i])).join(' | ') + ' |\n' + rule + '\n';

// Data rows
for (const r of rows) {
  text += '| ' + cols.map((c, i) => pad(r[c], colWidths[i])).join(' | ') + ' |\n';
}
text += rule;

// Return single item carrying the table string
return [
  {
    json: {
      tableAscii: text,
      recordCount: rows.length,
    },
  },
];

