               '<td style="padding:8px;border-bottom:1px solid #eee;">' +
                 entry[1] +
               '</td>' +
             '</tr>';
    })
    .join('');

  // Wrap the rows in a table
  return '<table style="margin:20px auto;width:100%;max-width:720px;border-collapse:collapse;font-family:Inter,Arial,sans-serif;font-size:14px;">' +
           '<tbody>' +
             rows +
           '</tbody>' +
         '</table>';

})
.join('')  // Combine all tables into one HTML string
}}

